using AIpet.Core;
using System.Text.Json;
namespace AIpet.Core.Tests;

// Assertions follow Tests/CoreTests.swift in source order.
public sealed class CoreTests : TestSupport
{
    [Fact]
    public void TranscriptStatesTailMonitorHooksAndScreenFocus()
    {
        var now = DateTimeOffset.UtcNow.AddSeconds(-20);
        var codex = new TranscriptDecoder(Provider.Codex, "one");
        codex.Consume(Record("session_meta", new { id = "one", cwd = "/work/project" }, now));
        Check(codex.Consume(Record("event_msg", new { type = "task_started", turn_id = "turn1" }, now))?.State == WorkState.Running, "Codex start");
        Check(codex.Consume(Record("event_msg", new { type = "task_complete", turn_id = "old" }, now)) is null, "mismatched completion ignored");
        Check(codex.Consume(Record("response_item", new { type = "function_call", name = "request_user_input" }, now))?.State == WorkState.Waiting, "Codex input");
        Check(codex.Consume(Record("response_item", new { type = "function_call_output" }, now))?.State == WorkState.Running, "Codex resumed");
        var completed = codex.Consume(Record("event_msg", new { type = "task_complete", turn_id = "turn1", last_agent_message = "PRIVATE" }, now))!;
        Check(completed.State == WorkState.Responded && completed.Project == "project", "completion is response, not success");
        Check(codex.Consume(Record("response_item", new { type = "reasoning" }, now)) is null, "finished turn not revived");
        Check(codex.Consume(Record("token_usage_record", new { type = "usage" }, now)) is null, "usage is not work");
        codex.Consume(Record("event_msg", new { type = "task_started", turn_id = "turn2" }, now.AddSeconds(1)));
        Check(codex.Consume(Record("event_msg", new { type = "turn_aborted", turn_id = "turn2" }, now.AddSeconds(2)))?.State == WorkState.Interrupted, "interrupted distinct from completion");
        var child = new TranscriptDecoder(Provider.Codex, "child");
        child.Consume(Record("session_meta", new { id = "child", parent_thread_id = "one" }, now));
        Check(child.Consume(Record("event_msg", new { type = "task_started", turn_id = "t" }, now)) is null, "subagent not counted as separate parent");
        var claude = new TranscriptDecoder(Provider.Claude, "two");
        JsonElement ClaudeRecord(string type, object message, Dictionary<string, object>? extra = null)
        {
            var result = new Dictionary<string, object> { ["type"] = type, ["sessionId"] = "two", ["promptId"] = "p1", ["timestamp"] = now.ToString("O"), ["message"] = message, ["cwd"] = "/work/project" };
            if (extra is not null) foreach (var pair in extra) result[pair.Key] = pair.Value;
            return J(result);
        }
        Check(claude.Consume(ClaudeRecord("user", new { content = "SECRET PROMPT" }))?.State == WorkState.Running, "Claude prompt");
        Check(claude.Consume(ClaudeRecord("assistant", new { content = new[] { new { type = "tool_use", name = "Bash" } }, stop_reason = "tool_use" }))?.State == WorkState.Running, "tool use not completion");
        Check(claude.Consume(ClaudeRecord("assistant", new { content = new[] { new { type = "tool_use", name = "AskUserQuestion" } } }))?.State == WorkState.Waiting, "Claude input wait");
        Check(claude.Consume(ClaudeRecord("user", new { content = new[] { new { type = "tool_result" } } }))?.TurnID == "p1", "tool result retains turn");
        Check(claude.Consume(ClaudeRecord("assistant", new { content = new[] { new { type = "thinking" } }, stop_reason = "end_turn" }))?.State == WorkState.Running, "thinking block not final response");
        Check(claude.Consume(ClaudeRecord("assistant", new { content = new[] { new { type = "text", text = "PRIVATE" } }, stop_reason = "end_turn" }))?.State == WorkState.Responded, "Claude response end");
        Check(claude.Consume(ClaudeRecord("assistant", new { }, new() { ["isApiErrorMessage"] = true }))?.State == WorkState.Failed, "API error distinct");
        Check(claude.Consume(ClaudeRecord("user", new { content = "injected" }, new() { ["isMeta"] = true })) is null, "meta not user work");
        Check(claude.Consume(ClaudeRecord("user", new { content = "subagent" }, new() { ["isSidechain"] = true })) is null, "sidechain ignored");
        Check(claude.Consume(J(new { type = "cost-state", totalCostUSD = 10 })) is null, "cost update not work");
        var path = Path.Combine(Root, "one.jsonl");
        var start = Line(Record("event_msg", new { type = "task_started", turn_id = "one" }, now));
        File.WriteAllBytes(path, start[..^3]);
        var tail = new TranscriptTail(path, Provider.Codex);
        Check(tail.Read().Count == 0, "partial line held");
        using (var handle = new FileStream(path, FileMode.Append)) handle.Write(start[^3..]);
        Check(tail.Read().Count == 1, "partial line completed once");
        Check(tail.Read().Count == 0, "no duplicate on reread");
        AtomicWrite(path, Line(Record("event_msg", new { type = "task_complete", turn_id = "one" }, now)));
        Check(tail.Read().LastOrDefault()?.State == WorkState.Responded, "rotation reload");
        AtomicWrite(path, System.Text.Encoding.UTF8.GetBytes("not-json\n"));
        Check(tail.Read().Count == 0 && tail.LastError is null, "malformed record skipped");
        File.Delete(path);
        Check(tail.Read().Count == 0 && tail.LastError is not null, "missing file reported");
        var active = completed with { State = WorkState.Running };
        Check(active.Effective(now.AddSeconds(301)).State == WorkState.Unknown, "stale running not success");
        Check(completed.Effective(now.AddSeconds(301)).State == WorkState.Responded, "terminal preserved");
        var monitor = new StatusMonitor(Path.Combine(Root, "absent"), Path.Combine(Root, "absent2"), Path.Combine(Root, "absent3"));
        monitor.Merge(completed); monitor.Merge(completed with { UpdatedAt = now.AddSeconds(-1), State = WorkState.Running });
        var snapshot = monitor.Poll(now);
        Check(snapshot.Tasks.FirstOrDefault()?.State == WorkState.Responded, "out of order event rejected");
        Check(snapshot.Connections.All(c => !c.Available), "missing connection not zero success");
        monitor.Merge(completed with { Provider = Provider.Claude });
        Check(monitor.Poll(now).Tasks.Count == 2, "provider namespace isolation");
        var encoded = JsonData.Sorted(snapshot);
        Check(!encoded.Contains("PRIVATE") && !encoded.Contains("SECRET"), "no transcript body in snapshot");
        var hook = HookBridge.Item(Provider.Claude, J(new { session_id = "hook1", hook_event_name = "PermissionRequest", cwd = "/x/project", tool_input = new { secret = "PRIVATE" } }), now)!;
        Check(hook.State == WorkState.Waiting && hook.Source == "공식 훅", "permission hook");
        Check(HookBridge.Item(Provider.Claude, J(new { session_id = "x", hook_event_name = "Notification", notification_type = "auth_success" })) is null, "irrelevant hook ignored");
        Check(HookBridge.Item(Provider.Claude, J(new { session_id = "x", hook_event_name = "Stop", background_tasks = new[] { new { id = "b" } } }))?.State == WorkState.Running, "background work not marked done");
        Check(HookBridge.DecodeEvent(J(new { version = 99 })) is null, "unknown event version rejected");
        var attention = new ComputerUseActivity();
        attention.Start("functions.exec", "shell", now);
        Check(attention.ExpiresAt(now) is null, "terminal is not computer use");
        attention.Start("mcp__cua_repl.js", "screen", now); attention.Start("computer", "screen2", now); attention.Finish("unrelated", now);
        Check(attention.ExpiresAt(now) is not null, "screen tool pending");
        attention.Finish("screen", now);
        Check(attention.ExpiresAt(now.AddSeconds(4)) is not null, "parallel screen call remains active");
        attention.Finish("screen2", now);
        Check(attention.ExpiresAt(now.AddSeconds(4)) is null, "screen activity ends after short grace");
        attention.Start("computer", "lost", now);
        Check(attention.ExpiresAt(now.AddSeconds(61)) is null, "missing output expires");
        attention.Reset(); attention.Start("computer", "old", now); attention.Start("computer", "new", now.AddSeconds(1));
        attention.Finish("new", now.AddSeconds(2), J("Window: \"New\", App: B.")); attention.Finish("old", now.AddSeconds(3), J("Window: \"Old\", App: A."));
        Check(attention.Target?.AppName == "B", "late earlier call cannot replace newer window metadata");
        attention.Start("computer", "ambiguous", now.AddSeconds(4)); attention.Finish("ambiguous", now.AddSeconds(5), J("Window: \"A\", App: A.\nWindow: \"B\", App: B."));
        Check(attention.Target is null, "ambiguous observation clears previous target");
        var screenCodex = new TranscriptDecoder(Provider.Codex, "screen-session");
        var screenCall = Record("response_item", new { type = "function_call", @namespace = "mcp__cua_repl", name = "js", call_id = "cua1", arguments = "PRIVATE" }, now);
        screenCodex.Consume(screenCall);
        Check(screenCodex.ComputerUse.ExpiresAt(now) is not null, "Codex screen tool detected");
        screenCodex.Consume(Record("response_item", new { type = "function_call_output", call_id = "cua1" }, now));
        Check(screenCodex.ComputerUse.ExpiresAt(now.AddSeconds(4)) is null, "Codex output closes matching call");
        screenCodex.Consume(screenCall); screenCodex.Consume(Record("event_msg", new { type = "task_complete" }, now));
        Check(screenCodex.ComputerUse.ExpiresAt(now) is null, "completed task clears screen attention");
        screenCodex.Consume(screenCall);
        Check(screenCodex.ComputerUse.ExpiresAt(now) is null, "completed task ignores late screen calls");
        var screenClaude = new TranscriptDecoder(Provider.Claude, "screen-claude");
        screenClaude.Consume(ClaudeRecord("assistant", new { content = new[] { new { type = "tool_use", name = "computer", id = "screenC" } } }));
        Check(screenClaude.ComputerUse.ExpiresAt(now) is not null, "Claude computer use detected");
        screenClaude.Consume(ClaudeRecord("user", new { content = new[] { new { type = "tool_result", tool_use_id = "screenC" } } }));
        Check(screenClaude.ComputerUse.ExpiresAt(now.AddSeconds(4)) is null, "Claude tool result closes matching call");
        var sessions = Path.Combine(Root, "sessions"); Directory.CreateDirectory(sessions);
        File.WriteAllBytes(Path.Combine(sessions, "screen-session.jsonl"), Line(screenCall));
        var screenMonitor = new StatusMonitor(Root, Path.Combine(Root, "no-claude"), Path.Combine(Root, "no-hooks"));
        var screenSnapshot = screenMonitor.Poll(now);
        Check(screenSnapshot.ScreenUseUntil is not null, "screen activity reaches UI snapshot");
        Check(!JsonData.Sorted(screenSnapshot).Contains("PRIVATE"), "screen arguments not retained");
        var runningCodex = completed with { State = WorkState.Running }; var runningClaude = runningCodex with { Provider = Provider.Claude };
        Check(PetTaskSummary.RunningHeadline([runningClaude, runningCodex]) == "Codex · Claude Code · 작업 중", "both AI names shown in bubble");
        Check(PetTaskSummary.RunningHeadline([runningCodex, runningCodex]) == "Codex · 2개 작업 중", "same provider groups task count");
        Check(PetTaskSummary.RunningHeadline([runningClaude, completed]) is null, "finished AI excluded from running summary");
        Check(PetTaskSummary.RunningDetail([runningClaude, runningCodex]) == "Codex 1 · Claude Code 1", "urgent bubble still lists running AI names");
        var codexDir = Path.Combine(Root, "focus-codex"); var claudeDir = Path.Combine(Root, "focus-claude"); Directory.CreateDirectory(codexDir); Directory.CreateDirectory(claudeDir);
        var codexPath = Path.Combine(codexDir, "owner-codex.jsonl"); var claudePath = Path.Combine(claudeDir, "owner-claude.jsonl");
        JsonElement Cr(string type, object content, DateTimeOffset date, string? reason = null) => J(new { type, sessionId = "owner-claude", uuid = "claude-turn", timestamp = date.ToString("O"), message = new { content, stop_reason = reason } });
        File.WriteAllBytes(codexPath, Line(Record("event_msg", new { type = "task_started", turn_id = "codex-turn" }, now.AddSeconds(-100))));
        Append(codexPath, screenCall);
        Append(codexPath, Record("response_item", new { type = "function_call_output", call_id = "cua1", output = new[] { new { type = "input_text", text = "Window: \"Work\", App: AIpet.\nPRIVATE BODY" } } }, now));
        File.WriteAllBytes(claudePath, Line(Cr("user", "PRIVATE PROMPT", now.AddSeconds(-50))));
        Append(claudePath, Cr("assistant", new[] { new { type = "tool_use", name = "computer", id = "claude-screen" } }, now.AddSeconds(-1)));
        var focusMonitor = new StatusMonitor(codexDir, claudeDir, Path.Combine(Root, "no-hooks")); var firstFocus = focusMonitor.Poll(now);
        Check(firstFocus.ScreenFocus?.Provider == Provider.Codex, "monitor selects older overall task even when Claude began screen use first");
        Check(Math.Abs((firstFocus.ScreenFocus!.TaskStartedAt!.Value - now.AddSeconds(-100)).TotalSeconds) < 0.01, "task start survives screen output updates");
        Check(firstFocus.ScreenFocus?.Target?.AppName == "AIpet", "matched screen output metadata reaches snapshot");
        Check(!JsonData.Sorted(firstFocus).Contains("PRIVATE"), "focus metadata excludes prompt and observation body");
        Append(claudePath, Cr("assistant", new[] { new { type = "tool_use", name = "computer", id = "claude-screen2" } }, now.AddSeconds(1)));
        Check(focusMonitor.Poll(now.AddSeconds(1)).ScreenFocus?.Provider == Provider.Codex, "newer screen events do not steal older task priority");
        Append(codexPath, Record("event_msg", new { type = "task_complete", turn_id = "codex-turn" }, now.AddSeconds(2)));
        Check(focusMonitor.Poll(now.AddSeconds(2)).ScreenFocus?.Provider == Provider.Claude, "completion hands focus to next active AI");
        Append(codexPath, Record("event_msg", new { type = "task_started", turn_id = "codex-next" }, now.AddSeconds(3)));
        Append(codexPath, Record("response_item", new { type = "function_call", name = "computer", call_id = "new-codex-screen" }, now.AddSeconds(3)));
        Check(focusMonitor.Poll(now.AddSeconds(3)).ScreenFocus?.Provider == Provider.Claude, "reused Codex session gets a new task start");
        Append(claudePath, Cr("assistant", new[] { new { type = "text", text = "PRIVATE RESPONSE" } }, now.AddSeconds(4), "end_turn"));
        Check(focusMonitor.Poll(now.AddSeconds(4)).ScreenFocus?.Provider == Provider.Codex, "Claude end_turn releases focus");
        Check(focusMonitor.Poll(now.AddSeconds(64)).ScreenFocus is null, "lost result expires rather than holding focus forever");
    }
}
